/**
 * Deliberate kart identities, second half of the universe catalogue.
 * These are miniature racing adaptations, never a claim of a 1:1 licensed asset.
 * Source URLs describe references actually consulted; the roster adds each hero's
 * existing references and incarnation separately. Empty URLs mean local briefs.
 * No category, array index, random seed or colour decides a vehicle identity.
 */
const design = (label, model, motifs, recognition, colors, options = {}) => Object.freeze({
  label, model,
  motifs: Object.freeze(motifs.split(' ')),
  sourceKind: 'universe-invention', referenceVehicle: null,
  recognition: Object.freeze(recognition.split(' | ')),
  rationale: 'Création kart propre à cet univers : la forme et les accessoires priment sur une simple livrée.',
  sourceUrls: Object.freeze([]),
  ...(colors ? { color: colors[0], accent: colors[1], detailColor: colors[2] || '#dbe8ec' } : {}),
  ...options
});
const canonical = (vehicle, urls = []) => ({
  sourceKind: 'canonical-vehicle-adaptation', referenceVehicle: vehicle,
  rationale: 'Véhicule de référence compacté pour la course, avec poste de conduite ouvert pour le sprite du personnage ; géométrie artistique à revoir.',
  sourceUrls: Object.freeze(urls)
});
const original = { sourceKind: 'original-universe-design', rationale: 'Création de véhicule rattachée au lore original de Multiverse ; les éléments cités proviennent de cet univers.' };
