/** Character exceptions are authored from the selected character and equipment.
 * Sharing a base vehicle inside one faction is intentional; these overrides
 * separate other factions, personal vehicles and clearly different silhouettes.
 */
const variant = (universe, label, model, motifs, recognition, options = {}) => Object.freeze({
  ...UNIVERSE_KART_IDENTITIES_B[universe], label, model,
  ...(model !== UNIVERSE_KART_IDENTITIES_B[universe].model ? { variant: null } : {}),
  motifs: Object.freeze(motifs.split(' ')),
  recognition: Object.freeze(recognition.split(' | ')), ...options
});

